(1600,	1364,	'_elementor_data',	'[{\"id\":\"b61c180\",\"elType\":\"section\",\"settings\":{\"layout\":\"full_width\",\"gap\":\"no\"},\"elements\":[{\"id\":\"5641577\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[],\"isInner\":false}],\"isInner\":false},{\"id\":\"6f777e2\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"margin\":{\"unit\":\"px\",\"top\":\"-100\",\"right\":0,\"bottom\":\"0\",\"left\":0,\"isLinked\":false},\"layout\":\"full_width\",\"content_width\":{\"unit\":\"px\",\"size\":1600,\"sizes\":[]}},\"elements\":[{\"id\":\"dc52cf0\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"content_position\":\"top\"},\"elements\":[{\"id\":\"165a187\",\"elType\":\"widget\",\"settings\":{\"sec_subtitle\":\"\",\"sec_title\":\"Congo Leadership\\nInstitute\",\"sec_animation_text\":\"\\t<b class=\\\"is-visible\\\"> N\\u00e9h\\u00e9mie<\\/b>\\n\\t\\t\\t\\t\\t\\t\\t\\t<b> Esther<\\/b>\\n<b> Archad<\\/b>\\n<b> Al\\u00e9rion<\\/b>\\n\\t\\t\\t\\t\\t\\t\\t\\t\",\"sec_content\":\"CLI existe pour accompagner au travers la formation et encadrement un nouveau type de Leaders qui sera au centre du d\\u00e9veloppement de notre pays sur le plan politique, \\u00e9conomique, des affaires, religieux, scientifique, etc. \",\"sec_1st_btn_text\":\"Trouver une formation\",\"sec_1st_btn_link\":\"# \",\"sec_2nd_btn_text\":\"Commencer\",\"sec_2nd_btn_link\":\"# \",\"sec_secimage\":{\"url\":\"http:\\/\\/cli.local\\/wp-content\\/uploads\\/2025\\/10\\/cli-logo.jpg\",\"id\":1248,\"size\":\"\",\"alt\":\"cli logo\",\"source\":\"library\"},\"sec_bg_color\":\"#040A08F2\",\"_element_width\":\"inherit\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"none\",\"sec_style\":\"2\"},\"elements\":[],\"widgetType\":\"edumel-banner\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"add4cb3\",\"elType\":\"section\",\"settings\":{\"layout\":\"full_